head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > showSortableUseFilter]<br/>sortable=true 일때 정렬 상태 아이콘과 필터 버튼을 Header Column 에 함께 표시할지 설정합니다.",
    "validation" : [
        "showSortableUseFilter=true 면 정렬 상태 아이콘과 필터 버튼을 Header Column 에 함께 표시하며, 정렬 상태 아이콘과 필터 버튼을 div 요소로 감싸서 렌더링해야 합니다.",
        "showSortableUseFilter=false(기본값)면 정렬 상태 아이콘만 Header Column 에 표시하고, 필터 버튼은 Header Column 에 표시되지 않아야 합니다.",
        "showSortableImage=true 이고 Header Column 의 useFilter=true 일때 동작해야 합니다.",
        "showSortableImage=false 이거나 headerFilter=true 이면 showSortableUseFilter 속성은 무시되어야 합니다.",
        "showSortableUseFilter=true 이면 'w2grid_head_sort_div_main_outer_box', 'w2grid_customFilter_sortable_open', 'w2grid_head_sort_usefilter_div_main' CSS 클래스가 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 속성별 con_ selectbox 로 각각 독립 설정 (공통 gdl_boolean 바인딩 → getText() 로 label('' / 'true' / 'false') 판단)
    //  - con_showSortableUseFilter : '' 미설정(기본 false) / 'true' / 'false'
    //  - con_showSortableImage     : '' 미설정 / 'true' / 'false'  (전제조건/무시조건 검증)
    //  - con_headerFilter          : '' 미설정 / 'true' / 'false'  (무시조건 검증)
    let vUseFilter = con_showSortableUseFilter.getText();
    let vShowImg = con_showSortableImage.getText();
    let vHeaderFilter = con_headerFilter.getText();

    // 정렬 가능한 Header Column 이어야 정렬 아이콘/필터 버튼이 의미를 가지므로 항상 sortable: true
    let properties = {
        sortable: true,
    };

    // showSortableUseFilter : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vUseFilter === 'true') {
        properties.showSortableUseFilter = true;
    } else if (vUseFilter === 'false') {
        properties.showSortableUseFilter = false;
    }
    // showSortableImage : 미설정('') 이면 속성 미추가 (showSortableUseFilter 전제조건)
    if (vShowImg === 'true') {
        properties.showSortableImage = true;
    } else if (vShowImg === 'false') {
        properties.showSortableImage = false;
    }
    // headerFilter : 미설정('') 이면 속성 미추가 (true 면 무시조건)
    if (vHeaderFilter === 'true') {
        properties.headerFilter = true;
    } else if (vHeaderFilter === 'false') {
        properties.headerFilter = false;
    }

    let lblDesc = 'sortable=true'
        + ', showSortableUseFilter=' + (vUseFilter === '' ? '(미설정)' : vUseFilter)
        + ', showSortableImage=' + (vShowImg === '' ? '(미설정)' : vShowImg)
        + ', headerFilter=' + (vHeaderFilter === '' ? '(미설정)' : vHeaderFilter);

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + ' / Header Column 들에 useFilter=true 설정"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // Header Column 에 useFilter="true" 를 직접 설정한 커스텀 gridView 생성
    //  (createBasicGridView 는 useFilter 미지원 → 인라인 구성으로 useFilter 전제조건 충족)
    await scwin.createUseFilterGridView(cList);
}



// useFilter="true" Header Column 을 가진 gridView 동적 생성 (마지막 컬럼 width="*", 가로 스크롤 방지)
scwin.createUseFilterGridView = async function (cList) {
    let grp_comp = document.querySelector('.tc_group_basic');
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:500px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 정렬/필터 표시 확인 :
//  각 sortable Header th 에서 정렬 아이콘 표시 여부 + 필터 버튼(input.w2grid_customFilter_open) 존재 여부
//  + div 래핑(w2grid_head_sort_div_main_outer_box) + 관련 CSS 클래스 적용 여부를 출력.
//  (정렬/필터 조작은 사용자 클릭으로 수행 → 별도 트리거 버튼 생성하지 않음)
scwin.btn_checkFilter_onclick = function (e) {
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (!headTable) {
        wf_body_bottom.getObj("scwin").setReturnValue("head_table 를 찾을 수 없습니다.");
        return;
    }

    let sortableThs = headTable.querySelectorAll("th.w2grid_head_sortable");
    if (sortableThs.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("sortable Header Column(th.w2grid_head_sortable) 이 없습니다.");
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[옵션] showSortableUseFilter : " + target1.options.showSortableUseFilter + " / showSortableImage : " + target1.options.showSortableImage + " / headerFilter : " + target1.options.headerFilter);

    for (let i = 0; i < sortableThs.length; i++) {
        let th = sortableThs[i];

        // 필터 버튼 : useFilter 컬럼은 th 안에 input.w2grid_customFilter_open 으로 렌더링됨
        let filterBtn = th.querySelector("input.w2grid_customFilter_open");
        let hasFilterBtn = !!filterBtn;

        // 정렬 상태 아이콘 클래스 (image_none 은 미표시 의미)
        let sortClasses = (th.outerHTML.match(/w2grid_head_sort\w*/g) || []);
        sortClasses = sortClasses.filter((v, idx) => sortClasses.indexOf(v) === idx);
        let iconStateClasses = sortClasses.filter(c => /sort_(asc|desc|none|image_none)/.test(c));
        let hasSortIcon = iconStateClasses.some(c => !/image_none/.test(c));

        // div 래핑 + CSS 클래스 (@spec2)
        let hasOuterBox = !!th.querySelector(".w2grid_head_sort_div_main_outer_box");
        let hasSortableOpen = !!th.querySelector(".w2grid_customFilter_sortable_open");
        let hasUseFilterDivMain = !!th.querySelector(".w2grid_head_sort_usefilter_div_main");

        wf_body_bottom.getObj("scwin").setReturnValue("Header[" + i + "] 정렬아이콘 표시 : " + hasSortIcon + " / 필터버튼 표시 : " + hasFilterBtn + " / div래핑(outer_box) : " + hasOuterBox + " / CSS(customFilter_sortable_open : " + hasSortableOpen + ", head_sort_usefilter_div_main : " + hasUseFilterDivMain + ")");
    }
}
